# fix-projects-tab.ps1
# Run this script from the root of the ViralForge project (same folder as package.json)
$ErrorActionPreference = "Stop"

$dashPath = Join-Path $PSScriptRoot "src\sections\Dashboard.tsx"
$apiPath = Join-Path $PSScriptRoot "api\get-projects.js"

if (-not (Test-Path (Join-Path $PSScriptRoot "package.json"))) {
    Write-Host "ERROR: package.json not found next to this script." -ForegroundColor Red
    Write-Host "Make sure fix-projects-tab.ps1 is placed directly in the project root." -ForegroundColor Red
    exit 1
}

$dashB64 = ""
$dashBytes = [System.Convert]::FromBase64String($dashB64)
[System.IO.File]::WriteAllBytes($dashPath, $dashBytes)
Write-Host "OK: $dashPath updated." -ForegroundColor Green

$apiB64 = ""
$apiBytes = [System.Convert]::FromBase64String($apiB64)
[System.IO.File]::WriteAllBytes($apiPath, $apiBytes)
Write-Host "OK: $apiPath created." -ForegroundColor Green

Set-Location $PSScriptRoot
git add .
git commit -m "Connect Projects tab to real Supabase data"
git push

Write-Host "Committed and pushed. Vercel will redeploy in a minute." -ForegroundColor Green
